"""ISA 표준대기 + WGS-84 지구모델 상수 (도메인 문서 01§2.5)."""

ISA_T0 = 288.15  # 해면 표준온도 [K]
ISA_P0 = 101325.0  # 해면 표준압력 [Pa]
ISA_RHO0 = 1.225  # 해면 표준밀도 [kg/m3]
ISA_LAPSE_RATE = -0.0065  # 대류권 기온감률 [K/m]
ISA_R_AIR = 287.05287  # 건조공기 비기체상수 [J/(kg·K)]
ISA_GAMMA_AIR = 1.4  # 비열비 [-]
ISA_TROPOPAUSE_ALT = 11000.0  # 대류권계면 고도 [m, 지오퍼텐셜]
ISA_STRATO1_TOP_ALT = 20000.0  # 등온 성층권 1층 상한 고도 [m, 지오퍼텐셜]
ISA_MIN_ALT = -5000.0  # 모델 유효 하한 고도 [m, 지오퍼텐셜]

EARTH_R0 = 6356766.0  # 지오퍼텐셜 변환 기준 지구반경 [m] (ISA/US Standard Atmosphere)

WGS84_A = 6378137.0  # 장반경 [m]
WGS84_B = 6356752.314245  # 단반경 [m]
WGS84_F = 1.0 / 298.257223563  # 편평률 [-]
WGS84_E2 = WGS84_F * (2.0 - WGS84_F)  # 제1이심률 제곱 [-]
WGS84_OMEGA = 7.292115e-5  # 지구 자전각속도 [rad/s]
WGS84_GM = 3.986004418e14  # 지구 중력상수 [m3/s2]
WGS84_GE = 9.7803253359  # 적도 정규중력 [m/s2]
WGS84_GP = 9.8321849378  # 극 정규중력 [m/s2]
WGS84_M = 0.00344978650684  # 원심력 보정 계수 ω²a²b/GM [-]
